import type OpenAI from 'openai';
import type { AgentRuntimeContextService } from './agent-runtime';
import type { UnifiedAgentActionsService } from './unified-agent-actions.service';
import { buildPredecidedActionDraft, executePredecidedAgentActions } from './unified-agent-predecided-actions.part';
import type { UnifiedAgentResponseService } from './unified-agent-response.service';
import { recordAgentRuntimeTurn } from './unified-agent-runtime.helpers';
import { actionSucceeded, executeToolAction, type ExecuteToolActionDeps } from './unified-agent-tool-router.helpers';
import type { ActionEntry, PredecidedAction } from './unified-agent.types';

type UnknownRecord = Record<string, unknown>;

type ProcessMessageResult = {
  actions: ActionEntry[];
  response?: string;
  intent: string;
  confidence: number;
};

export async function processUnifiedAgentPredecidedActions(params: {
  actions: UnifiedAgentActionsService;
  agentRuntime: AgentRuntimeContextService | undefined;
  contactId: string;
  fallbackWriterModel: string;
  message: string;
  openai: OpenAI | null;
  phone: string;
  predecidedActions: PredecidedAction[];
  response: UnifiedAgentResponseService;
  executeToolActionDeps: ExecuteToolActionDeps;
  workspaceId: string;
  writerModel: string;
  allowedTools?: string[];
  channel?: string;
  context?: UnknownRecord;
}): Promise<ProcessMessageResult | null> {
  if (params.predecidedActions.length === 0) {
    return null;
  }

  const actionsList = await executePredecidedAgentActions({
    ...(params.allowedTools !== undefined ? { allowedTools: params.allowedTools } : {}),
    contactId: params.contactId,
    ...(params.context !== undefined ? { context: params.context } : {}),
    executeTool: executeToolAction.bind(null, params.executeToolActionDeps),
    logAutopilotEvent: params.actions.logAutopilotEvent.bind(params.actions),
    phone: params.phone,
    predecidedActions: params.predecidedActions,
    workspaceId: params.workspaceId,
  });
  const intent = params.response.extractIntent(actionsList, params.message);
  const draftedReply = await params.response.composeWriterReply(
    params.openai,
    params.writerModel,
    params.fallbackWriterModel,
    {
      workspaceId: params.workspaceId,
      customerMessage: params.message,
      assistantDraft: buildPredecidedActionDraft(actionsList),
      actions: actionsList,
      historyTurns: 0,
    },
  );

  const confidence = actionsList.length > 0 ? 0.85 : 0.55;
  await recordAgentRuntimeTurn(params.agentRuntime, {
    workspaceId: params.workspaceId,
    channel: params.channel || 'whatsapp',
    userMessage: params.message,
    ...(draftedReply !== undefined ? { assistantMessage: draftedReply } : {}),
    contactId: params.contactId,
    intent,
    confidence,
    actions: actionsList.map((action) => ({
      toolName: action.tool,
      success: actionSucceeded(action.result),
      result: action.result,
    })),
  });

  return {
    actions: actionsList,
    ...(draftedReply !== undefined ? { response: draftedReply } : {}),
    intent,
    confidence,
  };
}
